  'assemble RNS': 'FA2132000000000000000004',
}
blocks = {k: block(v) for k, v in ids.items()}

def normalize(b, kind):
    if not b: return '<MISSING>'
    lines = b.splitlines()
    out = []
    for l in lines:
        if 'CODE_SIGN_ENTITLEMENTS' in l: l = 'CODE_SIGN_ENTITLEMENTS = <PIN>;'
        if 'MACOSX_DEPLOYMENT_TARGET' in l: l = '<FLOOR-LINE>'
